// 멤버십 전용 코드 — 유튜브 채널 멤버십 회원에게 커뮤니티 공지 등으로 배포
// 결제 시스템이 아니라 "회원 확인용 접근 코드"이므로 간단한 문자열 대조 방식
const MEMBER_CODE = "잼공가족2026";
const MEMBER_KEY = "jamgong-inyeonsachal-member";

function isMember() {
  return localStorage.getItem(MEMBER_KEY) === "true";
}

function getKakaoUser() {
  const id = localStorage.getItem('kakao-user-id');
  return id ? { id, nickname: localStorage.getItem('kakao-user-nickname') || '회원' } : null;
}

window.loginWithKakao = function(onSuccess) {
  // Kakao SDK 초기화 확인
  try {
    if (!window.Kakao) { alert('카카오 SDK 로딩 중입니다. 잠시 후 다시 시도해주세요.'); return; }
    if (!window.Kakao.isInitialized()) { window.Kakao.init('8469c650ee392a9ac9327e099027f9d3'); }
  } catch(e) { /* ignore */ }

  function doSuccess(nick) {
    localStorage.setItem('kakao-user-id', 'kakao-' + Date.now());
    localStorage.setItem('kakao-user-nickname', nick || '카카오 회원');
    if (onSuccess) onSuccess(nick); else location.reload();
  }

  function fetchMe() {
    try {
      Kakao.API.request({
        url: '/v2/user/me',
        success: function(res) {
          const nick = res.kakao_account?.profile?.nickname || res.properties?.nickname || '카카오 회원';
          localStorage.setItem('kakao-user-id', String(res.id));
          localStorage.setItem('kakao-user-nickname', nick);
          if (onSuccess) onSuccess(nick); else location.reload();
        },
        fail: function() { doSuccess('카카오 회원'); }
      });
    } catch(e) { doSuccess('카카오 회원'); }
  }

  // SDK 2.x: Kakao.Auth.login() 시도
  try {
    if (typeof Kakao.Auth?.login === 'function') {
      Kakao.Auth.login({
        throughTalk: false,
        success: function() { fetchMe(); },
        fail: function(err) {
          console.error('kakao login fail', err);
          // 팝업 차단 등의 경우 authorize로 fallback
          _kakaoAuthorize();
        }
      });
      return;
    }
  } catch(e) { /* fall through */ }

  _kakaoAuthorize();
};

function _kakaoAuthorize() {
  // redirect URI 방식: 현재 URL로 돌아옴
  try {
    Kakao.Auth.authorize({ redirectUri: window.location.origin });
  } catch(e) {
    alert('카카오 로그인을 지원하지 않는 환경입니다.\n멤버십 코드를 입력해주세요.');
  }
}

// 페이지 로드 시 카카오 OAuth redirect 처리
(function() {
  var params = new URLSearchParams(window.location.search);
  var code = params.get('code');
  if (code && !localStorage.getItem('kakao-user-id')) {
    // auth code 받음 → 간소화: 코드 존재 자체로 로그인 처리 (서버리스 환경)
    localStorage.setItem('kakao-user-id', 'kakao-auth-' + Date.now());
    localStorage.setItem('kakao-user-nickname', '카카오 회원');
    // URL에서 code 파라미터 제거
    var clean = window.location.pathname;
    history.replaceState({}, '', clean);
  }
})();

window.logoutKakao = function() {
  localStorage.removeItem('kakao-user-id');
  localStorage.removeItem('kakao-user-nickname');
  localStorage.removeItem(MEMBER_KEY);
  if (window.Kakao?.Auth?.getAccessToken()) {
    Kakao.Auth.logout(function() { location.reload(); });
  } else {
    location.reload();
  }
};

function tryUnlockMembership(code) {
  if (code.trim() === MEMBER_CODE) {
    localStorage.setItem(MEMBER_KEY, "true");
    return true;
  }
  return false;
}

const FALLBACK_LOCATION = { userLat: 37.5665, userLng: 126.9780, locationLabel: "서울특별시청 (기본값)" };

/** 브라우저 Geolocation API로 실제 위치 감지. 미지원/거부/타임아웃 시 서울시청으로 안전하게 폴백 */
function detectUserLocation() {
  return new Promise((resolve) => {
    if (!("geolocation" in navigator)) {
      resolve(FALLBACK_LOCATION);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        resolve({
          userLat: pos.coords.latitude,
          userLng: pos.coords.longitude,
          locationLabel: "현재 위치 감지됨",
        });
      },
      () => resolve(FALLBACK_LOCATION), // 사용자가 위치 권한 거부 시
      { timeout: 5000, maximumAge: 300000 }
    );
  });
}

