    history:'676년 의상대사 창건. 삼국유사 「의상전교(義湘傳敎)」에 기록: 의상이 당나라 유학 중 선묘라는 여인이 그를 사모했고, 의상이 귀국하자 선묘는 바다에 몸을 던져 용이 되어 그를 보호했다. 의상이 절터를 잡을 때 이교도들이 방해하자 선묘용이 커다란 바위를 공중에 띄워 위협해 이들을 쫓아냈다 — 이 "부석(浮石, 뜨는 돌)"이 절 이름의 유래. 무량수전은 현존 최고(最古) 목조건물 중 하나.',
