    desc:'한국에서 가장 오래된 사찰 — 372년 고구려 소수림왕 때 창건. "단군의 세 아들이 쌓은 정족산성 안에 위치"하며, 단군 신화와 불교가 만나는 유일한 성지. 대웅전 처마 나부 조각의 슬픈 전설이 유명.',
