    history:'372년(고구려 소수림왕 2년) 아도화상 창건 — 한국 불교 전래와 함께한 최초의 사찰. 선묘(仙妙)라는 여인이 옥등(玉燈)을 불전에 바쳐 "전등사(傳燈寺)"라 불림. 대웅전(보물 제178호) 처마 네 귀퉁이 나부상 전설: 목수가 사랑한 주막 여인이 공사비를 갖고 달아나자, 목수가 그 여인을 조각해 무거운 처마를 들고 있게 했다는 슬픈 이야기.',
